<?php require 'functions.php';$pageTitle='Semua Produk';$products=$pdo->query('SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id ORDER BY p.created_at DESC')->fetchAll();require 'header.php';?><style>.product-seller-byline{display:block;color:#876d53;font-size:11px;margin:3px 0 7px;line-height:1.4}</style><section class="section"><h2>Semua produk</h2><div class="products"><?php foreach($products as $p):?><article class="product"><a href="<?=url('product.php?id='.$p['id'])?>"><img src="<?=e(image_url($p['image']))?>"></a><div class="product-info"><small><?=e($p['category_name']??'Handmade')?></small><a class="product-name" href="<?=url('product.php?id='.$p['id'])?>"><?=e($p['name'])?></a><small class="product-seller-byline">Dijual oleh <?=e(product_seller_label($pdo,(int)($p['seller_id']??0)))?></small><b><?=rupiah($p['price'])?></b></div></article><?php endforeach;?></div></section><?php require 'footer.php';?>